	SetDepartmentCache(context.Context, *OneDepartmentRequest) (*v1.Bool, error)
	// 批量获取部门详情缓存
	MGetDepartmentCache(context.Context, *MultiDepartmentRequest) (*DepartmentMultiReply, error)
